mapper.select:
SELECT U.USER_ID , U.COMPANY_CODE , U.DIVISION_CODE , U.DEPT_NAME , U.EMP_NO , U.NAME_KOR , U.NAME_ENG , U.STATUS , COALESCE(R.ROLE_CODES, '') AS ROLE_CODES , COALESCE(R.ROLE_NAMES, '') AS ROLE_NAMES FROM USER_INFO U LEFT JOIN ( SELECT RU.USER_ID , RU.COMPANY_CODE , STRING_AGG(RU.ROLE_CODE, ', ' ORDER BY RU.ROLE_CODE) AS ROLE_CODES , STRING_AGG(RM.ROLE_NAME, ', ' ORDER BY RU.ROLE_CODE) AS ROLE_NAMES FROM ROLE_USER RU INNER JOIN ROLE_MST RM ON RM.ROLE_CODE = RU.ROLE_CODE AND RM.COMPANY_CODE = RU.COMPANY_CODE GROUP BY RU.USER_ID, RU.COMPANY_CODE ) R ON R.USER_ID = U.USER_ID AND R.COMPANY_CODE = U.COMPANY_CODE WHERE U.COMPANY_CODE = #{company_code}
AND U.STATUS = #{status}
AND U.DIVISION_CODE = #{division_code}
AND EXISTS (SELECT 1 FROM ROLE_USER RF WHERE RF.USER_ID = U.USER_ID AND RF.COMPANY_CODE = U.COMPANY_CODE AND RF.ROLE_CODE = #{role_code})
AND U.USER_ID ILIKE CONCAT('%', #{search_keyword}, '%')
AND (U.NAME_KOR ILIKE CONCAT('%', #{search_keyword}, '%') OR U.NAME_ENG ILIKE CONCAT('%', #{search_keyword}, '%'))
AND U.EMP_NO ILIKE CONCAT('%', #{search_keyword}, '%')
AND U.DEPT_NAME ILIKE CONCAT('%', #{search_keyword}, '%')
ORDER BY U.NAME_KOR, U.USER_ID

